// Iron Banners — Julius Caesar: the Gallic War, 58–50 BC (and the Rubicon, 49 BC).
'use strict';

// ---------- Late Republican Roman units
unit('rom_veteran', { name: 'Veteran Legion', cls: 'inf', era: 1, atk: 10, def: 9, mor: 90, tags: ['discipline', 'shock'], br: 2.4, hidden: true, note: 'Long-service professionals of the Marian legion: ten cohorts, a volley of pila, then the gladius. Caesar\'s Tenth was the most famous of all.' });
unit('rom_recruit', { name: 'New Legion', cls: 'inf', era: 1, atk: 7, def: 7, mor: 60, tags: ['shock'], br: 1.8, hidden: true, note: 'Freshly raised in Cisalpine Gaul, often at Caesar\'s own expense. Well armed, not yet hardened.' });
unit('rom_aux', { name: 'Auxilia', cls: 'missile', era: 1, atk: 5, def: 3, mor: 55, br: 1.2, hidden: true, note: 'Cretan archers, Balearic slingers and Numidian light troops hired to fight beside the legions.' });
unit('rom_scorpio', { name: 'Scorpions & Ballistae', cls: 'art', era: 1, atk: 9, def: 3, mor: 60, br: 1.8, hidden: true, note: 'Torsion bolt-throwers, about 60 to a ten-legion army. A scorpion bolt could pin a man to a tree.' });

// ---------- Gallic, Germanic and British units
unit('gaul_warrior', { name: 'Gallic Warriors', cls: 'inf', era: 1, atk: 7, def: 5, mor: 60, tags: ['shock'], br: 1.4, hidden: true, note: 'Tribal infantry with long slashing swords and big oval shields: a terrible first rush.' });
unit('gaul_noblecav', { name: 'Gallic Noble Cavalry', cls: 'hcav', era: 1, atk: 8, def: 5, mor: 65, tags: ['shock'], br: 1.9, hidden: true, note: 'Aristocrats and their sworn retainers, mounted, often in mail. The Romans learned the four-horned saddle from them.' });
unit('gaul_belgae', { name: 'Belgic Infantry', cls: 'inf', era: 1, atk: 8, def: 5, mor: 75, tags: ['shock'], br: 1.6, hidden: true, note: 'Caesar called the Belgae the bravest of the Gauls, because traders and their luxuries seldom reached them. The Nervii fought to the last man.' });
unit('germ_warband', { name: 'Germanic Warband', cls: 'inf', era: 1, atk: 8, def: 4, mor: 70, tags: ['shock'], br: 1.5, hidden: true, note: 'Suebi and their neighbors from beyond the Rhine, fighting by tribes and clans with their families watching from the wagons.' });
unit('germ_cav', { name: 'Germanic Cavalry', cls: 'lcav', era: 1, atk: 8, def: 5, mor: 80, tags: ['shock', 'feint'], br: 2.0, hidden: true, note: 'Horsemen who fought mixed with picked foot soldiers running beside them, holding the horses\' manes. Caesar hired them in 52 BC and they won him Alesia.' });
unit('brit_chariot', { name: 'British Chariots', cls: 'lcav', era: 1, atk: 7, def: 4, mor: 60, tags: ['feint', 'fear'], br: 1.6, hidden: true, note: 'Light two-horse chariots: the warrior threw javelins, leaped down to fight, and the driver waited nearby to whisk him away.' });

